import sys


def xargs_safe(path: str) -> bool:
    """Whether a path can be passed through whitespace-delimited xargs."""
    return not any(c in path for c in " \t\n\\\"'")


def printx_escape(path: str) -> str:
    """Escape paths as the reference -printx action does."""
    out = []
    for c in path:
        if c in " \t\n\\\"'":
            out.append("\\")
        out.append(c)
    return "".join(out)


def emit_printx(path: str, stream=None) -> None:
    if stream is None:
        stream = sys.stdout
    stream.write(printx_escape(path) + "\n")
