"""Helpers for bfs's ``-files0-from`` option."""

from __future__ import annotations


def roots_from_bytes(data: bytes) -> list[str]:
    """Decode NUL-separated filesystem roots.

    A final NUL is a separator, not an additional empty path.  An empty file
    therefore supplies no roots.
    """
    if not data:
        return []
    parts = data.split(b"\0")
    if parts[-1] == b"":
        parts.pop()
    return [part.decode(errors="surrogateescape") for part in parts]


def read_roots(filename: str, stdin=None) -> list[str]:
    """Read roots from *filename* (``-`` means the supplied stdin stream)."""
    if filename == "-":
        stream = stdin
        if stream is None:
            import sys
            stream = sys.stdin.buffer
        data = stream.read()
    else:
        with open(filename, "rb") as stream:
            data = stream.read()
    return roots_from_bytes(data)


def check_roots_conflict(explicit_paths: list[str]) -> None:
    """Raise the reference-compatible conflict message for explicit roots."""
    if explicit_paths:
        raise ValueError("Cannot combine -files0-from with explicit root paths.")

